@Composable
fun AnimatedPlayPauseIcon(
    isPlaying: Boolean,
    modifier: Modifier = Modifier,
    size: Dp = 32.dp,
    tint: Color = Color.Unspecified
) {
    val rotation by animateFloatAsState(
        targetValue = if (isPlaying) 180f else 0f,
